package com.emssystem.emsleaveservice.shared.entity; import jakarta.persistence.*; import org.springframework.data.annotation.CreatedDate; import org.springframework.data.annotation.LastModifiedDate; import org.springframework.data.jpa.domain.support.AuditingEntityListener; import java.time.Instant;
@MappedSuperclass @EntityListeners(AuditingEntityListener.class) public abstract class AuditableEntity{@CreatedDate @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;@LastModifiedDate @Column(name="updated_at",nullable=false) private Instant updatedAt;@Version @Column(nullable=false) private long version;public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public long getVersion(){return version;}}
